import{_ as e,o as n,c,a5 as o}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"08 — Gói Cước, Thanh Toán SePay (VietQR) & Ví AI Credit (Subscription & Billing)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/08-subscription-billing.md","filePath":"ba/08-subscription-billing.md"}'),d={name:"ba/08-subscription-billing.md"};function i(a,t,l,s,g,r){return n(),c("div",null,[...t[0]||(t[0]=[o('<h1 id="_08-—-goi-cuoc-thanh-toan-sepay-vietqr-vi-ai-credit-subscription-billing" tabindex="-1">08 — Gói Cước, Thanh Toán SePay (VietQR) &amp; Ví AI Credit (Subscription &amp; Billing) <a class="header-anchor" href="#_08-—-goi-cuoc-thanh-toan-sepay-vietqr-vi-ai-credit-subscription-billing" aria-label="Permalink to &quot;08 — Gói Cước, Thanh Toán SePay (VietQR) &amp; Ví AI Credit (Subscription &amp; Billing)&quot;">​</a></h1><p>&gt; Navigation: <a href="./README.html">← BA Overview &amp; Hub</a> · <a href="./07-publishing-social.html">← 07 - Publishing &amp; Social</a> · <a href="./09-admin-functions.html">Tiếp: 09 - Admin Functions →</a> &gt; &gt; <strong>Phạm vi FR chuẩn</strong>: <strong>Mục <code>3.9 Subscription &amp; Billing</code> — 6 FR (<code>3.9.1</code> – <code>3.9.6</code>)</strong> | <code>UC-122</code> – <code>UC-127</code> · Use Cases chi tiết: <a href="./use-cases/07-subscription.html">use-cases/07-subscription.md</a> · Đặc tả SRS: <a href="./../feature/srs/08-subscription-billing/README.html">08-subscription-billing</a>. &gt; Tuân thủ tuyệt đối <code>AGENTS.md</code> (<strong>Không có Downgrade Plan</strong>, <strong>Chỉ sử dụng cổng thanh toán SePay (VietQR)</strong>) và mô hình tài chính chi tiết tại <code>brandhub-pricing-model.xlsx</code>.</p><hr><h2 id="_1-bang-tong-hop-6-yeu-cau-chuc-nang-chuan-3-9-1-–-3-9-6" tabindex="-1">1. Bảng Tổng hợp 6 Yêu cầu Chức năng Chuẩn (<code>3.9.1</code> – <code>3.9.6</code>) <a class="header-anchor" href="#_1-bang-tong-hop-6-yeu-cau-chuc-nang-chuan-3-9-1-–-3-9-6" aria-label="Permalink to &quot;1. Bảng Tổng hợp 6 Yêu cầu Chức năng Chuẩn (`3.9.1` – `3.9.6`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (141-FR Baseline)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.9.1</code></strong></td><td style="text-align:center;"><code>UC-122</code></td><td style="text-align:left;"><strong>Upgrade Plan</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Nâng cấp gói đăng ký dịch vụ từ gói mặc định lên gói cao hơn trên <code>/subscription/plans</code> (<strong>chỉ hỗ trợ nâng cấp lên cấp cao hơn, đã lược bỏ luồng hạ cấp gói trực tiếp</strong>, <code>BR-15</code>, <code>BR-58</code>, <code>BR-59</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.9.2</code></strong></td><td style="text-align:center;"><code>UC-123</code></td><td style="text-align:left;"><strong>Make Payment (SePay)</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Thực hiện thanh toán đơn hàng nâng cấp gói cước hoặc mua thêm AI Credit thông qua cổng <strong>SePay (VietQR)</strong> (<code>/billing/checkout/:transactionId</code>). Khởi tạo giao dịch <code>PENDING</code> tuân thủ ACID trong PostgreSQL; khi nhận Webhook chữ ký hợp lệ từ SePay sẽ xử lý bất biến (<code>idempotent</code>) chuyển sang <code>PAID</code> và kích hoạt ngay quyền lợi (<code>BR-58</code>–<code>BR-61</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.9.3</code></strong></td><td style="text-align:center;"><code>UC-124</code></td><td style="text-align:left;"><strong>View Invoice History</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Xem lịch sử toàn bộ các giao dịch thanh toán (<code>PAID</code>, <code>PENDING</code>, <code>EXPIRED</code>, <code>FAILED</code>) và tải xuống hóa đơn điện tử dạng PDF tại <code>/billing/invoices</code> (<code>BR-15</code>, <code>BR-61</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.9.4</code></strong></td><td style="text-align:center;"><code>UC-125</code></td><td style="text-align:left;"><strong>View AI Credit Tracking</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Giám sát chi tiết lượng AI Credit đã tiêu thụ, lượng đang tạm giữ và số dư còn lại theo thời gian thực (<code>/billing/credits</code>) theo từng loại tác vụ AI, từng Workspace và kỳ thanh toán tháng (lượng credit định kỳ hàng tháng không cộng dồn sang tháng sau, <code>BR-48</code>, <code>BR-60</code>, <code>BR-64</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.9.5</code></strong></td><td style="text-align:center;"><code>UC-126</code></td><td style="text-align:left;"><strong>Buy Credit</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Mua bổ sung các gói nạp thêm AI Credit (<code>Top-up Credit Packs</code>) qua cổng <strong>SePay (VietQR)</strong> (<code>3.9.2</code>) và cộng ngay số lượng AI Credit mua thêm vào tổng quỹ khả dụng của Agency sau khi thanh toán thành công (<code>BR-15</code>, <code>BR-59</code>, <code>BR-60</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.9.6</code></strong></td><td style="text-align:center;"><code>UC-127</code></td><td style="text-align:left;"><strong>Set Credit</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Thiết lập và điều chỉnh hạn mức tiêu thụ AI Credit tối đa hàng tháng cho từng Workspace trực thuộc Agency (<code>/agency/:id/workspaces/:id/credit-limit</code>) sao cho không thấp hơn mức Workspace đó đã tiêu thụ trong kỳ hiện tại (<code>BR-15</code>, <code>BR-48</code>, <code>BR-60</code>, <code>BR-64</code>).</td></tr></tbody></table><hr><h2 id="_2-co-cau-2-dong-san-pham-6-goi-cuoc-chuan-subscription-plans" tabindex="-1">2. Cơ cấu 2 Dòng Sản phẩm &amp; 6 Gói Cước Chuẩn (<code>Subscription Plans</code>) <a class="header-anchor" href="#_2-co-cau-2-dong-san-pham-6-goi-cuoc-chuan-subscription-plans" aria-label="Permalink to &quot;2. Cơ cấu 2 Dòng Sản phẩm &amp; 6 Gói Cước Chuẩn (`Subscription Plans`)&quot;">​</a></h2><p>Hệ thống phục vụ cả người sáng tạo cá nhân (<code>Personal Studio</code>) và doanh nghiệp truyền thông (<code>Agency Suite</code>) thông qua <strong>2 dòng sản phẩm (6 gói cước)</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Dòng sản phẩm</th><th style="text-align:left;">Mã Gói Cước (<code>plan_code</code>)</th><th style="text-align:center;">Cấp bậc</th><th style="text-align:left;">Đặc trưng Quyền lợi &amp; Hạn mức</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1. BrandHub AI Studio</strong> <em>(Chế độ <code>PERSONAL</code> / Solo Creator)</em></td><td style="text-align:left;"><code>STUDIO_FREE</code> → <code>STUDIO_PLUS</code> → <code>STUDIO_PRO</code></td><td style="text-align:center;">3 bậc nâng cấp</td><td style="text-align:left;">Tối ưu cho cá nhân/nhóm nhỏ: cấp định mức <code>Plan Credit</code> hàng tháng tăng dần, dung lượng kho tư liệu, số kênh MXH cá nhân và hạn mức gửi bản tin.</td></tr><tr><td style="text-align:left;"><strong>2. BrandHub Agency Suite</strong> <em>(Chế độ <code>AGENCY</code> B2B)</em></td><td style="text-align:left;"><code>BASIC</code> → <code>PLUS</code> → <code>ENTERPRISE</code></td><td style="text-align:center;">3 bậc nâng cấp</td><td style="text-align:left;">Quản trị đa Workspace / đa <code>Client</code>: mở rộng số lượng Workspace, thành viên, kênh mạng xã hội, định mức gửi Email Newsletter (<code>1.000</code> / <code>10.000</code> / <code>50.000</code> email/tháng) và quỹ <code>Plan Credit</code> lớn.</td></tr></tbody></table><p>&gt; <strong>Quy tắc bất biến</strong>: Hệ thống chỉ cho phép <strong>nâng cấp lên gói cao hơn hoặc gia hạn (<code>3.9.1 Upgrade Plan</code>)</strong>; không hỗ trợ hạ cấp trực tiếp (<code>Downgrade Plan</code>).</p><hr><h2 id="_3-luong-thanh-toan-acid-qua-cong-sepay-vietqr-—-3-9-1-3-9-3" tabindex="-1">3. Luồng Thanh Toán ACID Qua Cổng SePay (VietQR — <code>3.9.1</code>..<code>3.9.3</code>) <a class="header-anchor" href="#_3-luong-thanh-toan-acid-qua-cong-sepay-vietqr-—-3-9-1-3-9-3" aria-label="Permalink to &quot;3. Luồng Thanh Toán ACID Qua Cổng SePay (VietQR — `3.9.1`..`3.9.3`)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Owner chọn Nâng cấp gói (3.9.1) hoặc Mua thêm Credit (3.9.5)]</span></span>\n<span class="line"><span>       │</span></span>\n<span class="line"><span>       ▼</span></span>\n<span class="line"><span>[Backend tạo Order + Transaction (status = PENDING) trong PostgreSQL kèm mã tham chiếu duy nhất]</span></span>\n<span class="line"><span>       │</span></span>\n<span class="line"><span>       ▼</span></span>\n<span class="line"><span>[Frontend hiển thị mã VietQR động của SePay (Ngân hàng, Số tài khoản, Số tiền, Nội dung tham chiếu)]</span></span>\n<span class="line"><span>       │</span></span>\n<span class="line"><span>       ├──(Owner quét QR trên ứng dụng Ngân hàng)──▶ [Cổng SePay ghi nhận biến động số dư]</span></span>\n<span class="line"><span>       │                                                       │</span></span>\n<span class="line"><span>       │                                                       ▼</span></span>\n<span class="line"><span>       │                                    [SePay gửi Webhook xác thực chữ ký về Backend (Idempotent)]</span></span>\n<span class="line"><span>       │                                                       │</span></span>\n<span class="line"><span>       ▼                                                       ▼</span></span>\n<span class="line"><span>[Trạng thái chuyển sang PAID] ──▶ [Kích hoạt gói Subscription mới / Cộng Credit vào agency_credit_wallets]</span></span></code></pre></div><hr><h2 id="_4-kien-truc-vi-ai-credit-cap-agency-tran-ngan-sach-workspace-3-9-4-–-3-9-6" tabindex="-1">4. Kiến trúc Ví AI Credit Cấp Agency &amp; Trần Ngân sách Workspace (<code>3.9.4</code> – <code>3.9.6</code>) <a class="header-anchor" href="#_4-kien-truc-vi-ai-credit-cap-agency-tran-ngan-sach-workspace-3-9-4-–-3-9-6" aria-label="Permalink to &quot;4. Kiến trúc Ví AI Credit Cấp Agency &amp; Trần Ngân sách Workspace (`3.9.4` – `3.9.6`)&quot;">​</a></h2><ol><li><strong>Một Ví Tổng cấp Agency (<code>agency_credit_wallets</code>) &amp; Hai Lớp Số dư</strong>: <ul><li><strong><code>Plan Credit</code> (Credit định kỳ theo gói)</strong>: Làm mới hàng tháng theo chu kỳ gói, không cộng dồn sang kỳ sau.</li><li><strong><code>Purchased Credit</code> (Credit mua thêm tại <code>3.9.5</code>)</strong>: Bảo lưu không hết hạn theo chu kỳ tháng.</li><li><strong>Thứ tự khấu trừ</strong>: Luôn ưu tiên trừ <code>Plan Credit</code> trước, hết <code>Plan Credit</code> mới trừ sang <code>Purchased Credit</code>.</li></ul></li><li><strong>Trần Ngân sách cấp Workspace (<code>workspace_credit_limits</code> — <code>3.9.6 Set Credit</code>)</strong>: <ul><li><code>Owner</code> cấu hình trần tiêu thụ hàng tháng cho từng Workspace (<code>cap = null</code> là không giới hạn riêng theo ví tổng; <code>cap = N &gt; 0</code> giới hạn tổng <code>used + held &lt;= N</code>; <code>cap = 0</code> khóa tác vụ tính phí trong Workspace đó).</li></ul></li><li><strong>Quy trình Giữ chỗ &amp; Quyết toán Nguyên tử (<code>ai_credit_reservations</code>)</strong>: <ul><li>Chỉ 4 nhóm tác vụ tính phí (<code>CONTENT_GENERATE</code>, <code>AMBASSADOR_GENERATE</code>, <code>COMMERCIAL_IMAGE</code>, <code>VIDEO_GENERATE</code>) trừ credit theo bảng đơn giá hệ thống (<code>3.10.10</code>–<code>3.10.12</code>).</li><li>Trước khi gọi sang <code>ai-service</code>, <code>business-service</code> khóa tạm credit (<code>HOLD</code>); khi AI hoàn tất mới chốt trừ (<code>SETTLE</code>), nếu AI lỗi hoặc timeout sẽ tự động hoàn trả 100% (<code>RELEASE</code>).</li></ul></li></ol><hr><h2 id="_5-bang-tham-chieu-quy-tac-nghiep-vu-br-58-–-br-61-br-64" tabindex="-1">5. Bảng Tham chiếu Quy tắc Nghiệp vụ (<code>BR-58</code> – <code>BR-61</code>, <code>BR-64</code>) <a class="header-anchor" href="#_5-bang-tham-chieu-quy-tac-nghiep-vu-br-58-–-br-61-br-64" aria-label="Permalink to &quot;5. Bảng Tham chiếu Quy tắc Nghiệp vụ (`BR-58` – `BR-61`, `BR-64`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã BR</th><th style="text-align:left;">Tên Quy tắc</th><th style="text-align:left;">Quy định Ràng buộc Cụ thể</th><th style="text-align:left;">FR Áp dụng</th></tr></thead><tbody><tr><td style="text-align:center;"><code>BR-58</code></td><td style="text-align:left;"><strong>Chỉ Nâng cấp Gói &amp; Áp dụng Tức thì Hạn mức</strong></td><td style="text-align:left;">Hệ thống chỉ cho phép nâng cấp lên bậc gói cao hơn trong cùng dòng hoặc nâng cấp từ dòng <code>STUDIO_*</code> lên dòng <code>Agency</code> (<code>BASIC</code>/<code>PLUS</code>/<code>ENTERPRISE</code>) hoặc gia hạn chu kỳ tháng/năm (<code>billing_plan_cycle_prices</code>); <strong>tuyệt đối không hỗ trợ luồng hạ cấp gói (<code>Downgrade Plan</code>)</strong>.</td><td style="text-align:left;"><code>3.9.1</code>, <code>3.9.2</code></td></tr><tr><td style="text-align:center;"><code>BR-59</code></td><td style="text-align:left;"><strong>Thanh toán Duy nhất qua SePay (VietQR) &amp; Xử lý Webhook Bất biến</strong></td><td style="text-align:left;">Mọi đơn hàng nâng cấp gói (<code>3.9.1</code>), mua thêm AI Credit (<code>3.9.5</code>) hoặc mua thêm dung lượng (<code>storage_addon_plans</code>) đều thanh toán qua <strong>SePay (VietQR)</strong>; sự kiện webhook từ SePay được ghi vào <code>billing_payment_events</code> và đối chiếu khóa chống trùng (<code>idempotent</code>) trước khi chuyển đơn sang <code>PAID</code> và cấp phát quyền lợi tại <code>billing_order_fulfillments</code>.</td><td style="text-align:left;"><code>3.9.2</code>, <code>3.9.5</code>, <code>3.10.13</code></td></tr><tr><td style="text-align:center;"><code>BR-60</code></td><td style="text-align:left;"><strong>Thứ tự Ưu tiên Khấu trừ Sổ cái Ví AI Credit</strong></td><td style="text-align:left;">Ví tổng <code>agency_credit_wallets</code> phân bổ từng lô <code>credit_grants</code>: luôn khấu trừ lô <code>Plan Credit</code> (có hạn theo kỳ tháng, không cộng dồn sang kỳ mới) trước, chỉ khi hết sạch mới khấu trừ sang lô <code>Purchased Credit</code> (mua thêm không hết hạn). Xem lại lịch sử nội dung cũ (<code>3.6.34</code>) không phát sinh bút toán trừ mới.</td><td style="text-align:left;"><code>3.9.4</code>–<code>3.9.6</code></td></tr><tr><td style="text-align:center;"><code>BR-61</code></td><td style="text-align:left;"><strong>Tính Bất biến của Chứng từ Hóa đơn &amp; Sổ cái Giao dịch</strong></td><td style="text-align:left;">Bản ghi <code>transactions</code>, <code>billing_payments</code> và <code>billing_audit_events</code> trong PostgreSQL là bất biến (append-only); mọi hóa đơn <code>PAID</code> đều có thể kết xuất chứng từ điện tử PDF và đối soát trực tiếp trên bảng doanh thu của <code>Admin</code>.</td><td style="text-align:left;"><code>3.9.2</code>, <code>3.9.3</code>, <code>3.10.13</code>, <code>3.10.14</code></td></tr><tr><td style="text-align:center;"><code>BR-64</code></td><td style="text-align:left;"><strong>Ràng buộc Trần Ngân sách Workspace &amp; Khóa Giá Tại Thời điểm Đặt chỗ</strong></td><td style="text-align:left;">Khi <code>Owner</code> cập nhật trần <code>workspace_credit_limits</code> (<code>3.9.6 Set Credit</code>), giá trị mới không được nhỏ hơn tổng credit mà Workspace đó đã tiêu thụ + đang giữ chỗ trong kỳ hiện hành; khi <code>Admin</code> đổi bảng giá (<code>3.10.11</code>), các lệnh <code>ai_credit_reservations</code> đã giữ chỗ trước đó vẫn quyết toán theo mức giá cũ lúc đặt chỗ.</td><td style="text-align:left;"><code>3.9.4</code>, <code>3.9.6</code>, <code>3.10.10</code>–<code>3.10.12</code></td></tr></tbody></table><hr><h2 id="_6-anh-xa-he-thong-bang-so-cai-postgresql-billing-v3-—-29-bang" tabindex="-1">6. Ánh xạ Hệ thống Bảng Sổ cái PostgreSQL (<code>Billing V3</code> — 29 Bảng) <a class="header-anchor" href="#_6-anh-xa-he-thong-bang-so-cai-postgresql-billing-v3-—-29-bang" aria-label="Permalink to &quot;6. Ánh xạ Hệ thống Bảng Sổ cái PostgreSQL (`Billing V3` — 29 Bảng)&quot;">​</a></h2><p>Toàn bộ dữ liệu tài chính và sổ cái AI Credit được lưu trữ độc quyền trên <strong>PostgreSQL 17</strong> (<code>brandhub-business-service</code>):</p><ul><li><strong>Danh mục &amp; Chu kỳ gói</strong>: <code>subscription_plans</code>, <code>billing_plan_versions</code>, <code>billing_plan_cycle_prices</code>, <code>billing_plan_change_log</code>, <code>user_subscriptions</code>, <code>subscription_plan_changes</code>, <code>agency_subscriptions</code>, <code>agency_subscription_periods</code>.</li><li><strong>Đơn hàng &amp; Thanh toán SePay</strong>: <code>billing_orders</code>, <code>billing_payment_attempts</code>, <code>billing_payment_events</code>, <code>billing_payments</code>, <code>billing_order_fulfillments</code>, <code>transactions</code>, <code>subscription_operational_issues</code>, <code>subscription_observation_jobs</code>, <code>subscription_provider_checks</code>.</li><li><strong>Sổ cái Kép AI Credit</strong>: <code>agency_credit_wallets</code>, <code>credit_grants</code>, <code>workspace_credit_limits</code>, <code>credit_usage_periods</code>, <code>workspace_credit_usage</code>, <code>ai_credit_operation_prices</code>, <code>ai_credit_reservations</code>, <code>credit_reservation_allocations</code>, <code>credit_operations</code>, <code>credit_entries</code>, <code>billing_outbox_events</code>, <code>billing_audit_events</code>.</li></ul><h3 id="lo-trinh-nang-cap-goi-cuoc-hop-le-upgrade-only-matrix" tabindex="-1">Lộ trình Nâng cấp Gói Cước Hợp lệ (<code>Upgrade-Only Matrix</code>) <a class="header-anchor" href="#lo-trinh-nang-cap-goi-cuoc-hop-le-upgrade-only-matrix" aria-label="Permalink to &quot;Lộ trình Nâng cấp Gói Cước Hợp lệ (`Upgrade-Only Matrix`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Gói Hiện tại</th><th style="text-align:left;">Các Gói Đích Được Phép Nâng Cấp (<code>3.9.1 Upgrade Plan</code>)</th><th style="text-align:left;">Quy tắc Chuyển đổi Quyền lợi</th></tr></thead><tbody><tr><td style="text-align:left;"><code>STUDIO_FREE</code></td><td style="text-align:left;"><code>STUDIO_PLUS</code>, <code>STUDIO_PRO</code>, <code>BASIC</code>, <code>PLUS</code>, <code>ENTERPRISE</code></td><td style="text-align:left;">Mở khóa ngay hạn mức mới sau khi đơn hàng <strong>SePay (VietQR)</strong> chuyển sang <code>PAID</code>.</td></tr><tr><td style="text-align:left;"><code>STUDIO_PLUS</code></td><td style="text-align:left;"><code>STUDIO_PRO</code>, <code>BASIC</code>, <code>PLUS</code>, <code>ENTERPRISE</code></td><td style="text-align:left;">Chuyển thẳng từ <code>Personal Studio</code> lên <code>Agency Suite</code> giữ nguyên 100% dữ liệu &amp; <code>Purchased Credit</code>.</td></tr><tr><td style="text-align:left;"><code>STUDIO_PRO</code></td><td style="text-align:left;"><code>BASIC</code>, <code>PLUS</code>, <code>ENTERPRISE</code></td><td style="text-align:left;">Nâng cấp sang vận hành đa <code>Workspace</code> / đa <code>Client</code> B2B.</td></tr><tr><td style="text-align:left;"><code>BASIC</code></td><td style="text-align:left;"><code>PLUS</code>, <code>ENTERPRISE</code></td><td style="text-align:left;">Mở rộng trần <code>Workspace</code>, thành viên, định mức gửi Newsletter và lô <code>Plan Credit</code> tháng.</td></tr><tr><td style="text-align:left;"><code>PLUS</code></td><td style="text-align:left;"><code>ENTERPRISE</code></td><td style="text-align:left;">Cấp bậc doanh nghiệp cao nhất (không có gói cao hơn; chỉ gia hạn chu kỳ hoặc mua thêm <code>Top-up Credit</code>).</td></tr></tbody></table>',25)])])}const u=e(d,[["render",i]]);export{p as __pageData,u as default};
